"use client";

import Link from "next/link";
import { ArrowRight, ExternalLink } from "lucide-react";
import { projects } from "@/data/projects";
import { cn } from "@/lib/utils";

export default function FeaturedProjects() {
  return (
    <section className="section-padding px-6 md:px-16 bg-background relative overflow-hidden">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-16 md:mb-32 gap-8 md:gap-10">
          <div className="max-w-2xl">
            <h2 className="h2 mb-4 uppercase leading-[1.25]">
              Featured <span className="text-white">Case</span> <br className="hidden md:block" />
              <span className="text-gradient">Studies.</span>
            </h2>
            <p className="text-foreground/60 text-base md:text-xl lg:text-2xl leading-relaxed max-w-2xl">
              Explore how we've helped startups and established companies 
              build scalable digital solutions that drive results.
            </p>
          </div>
          <Link 
            href="/projects" 
            className="group flex items-center gap-2 text-primary font-semibold hover:gap-4 transition-all pb-4 md:pb-6 uppercase text-xs tracking-widest"
          >
            View All Projects <ArrowRight className="w-5 h-5" />
          </Link>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 md:gap-16 lg:gap-24">
          {projects.slice(0, 4).map((project, index) => (
            <div 
              key={project.id}
              className="group relative overflow-hidden rounded-[2.5rem] bg-muted/30 border border-border/40 hover:border-primary/50 transition-all duration-500 hover:-translate-y-2 hover:shadow-2xl hover:shadow-primary/10 shine-effect"
            >
              {/* Image Container */}
              <div className="aspect-[16/10] overflow-hidden relative">
                <img 
                  src={project.thumbnail} 
                  alt={`${project.title} - ${project.description}`}
                  loading="lazy"
                  decoding="async"
                  className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-background via-background/20 to-transparent opacity-80" />
                
                {/* Overlay with Meta */}
                <div className="absolute top-6 right-6 md:top-8 md:right-8 flex flex-wrap justify-end gap-2 max-w-[200px]">
                  {project.tags.map(tag => (
                    <span key={tag} className="px-3 py-1 bg-black/40 backdrop-blur-md border border-white/10 rounded-full text-[9px] uppercase tracking-widest text-white/80 font-bold">
                      {tag}
                    </span>
                  ))}
                </div>
              </div>

              {/* Content */}
              <div className="p-8 md:p-12">
                <p className="text-primary text-[10px] md:text-xs font-bold uppercase tracking-[0.2em] mb-4">
                  {project.category}
                </p>
                <h3 className="text-2xl font-black mb-4 uppercase tracking-tighter group-hover:text-primary transition-colors font-outfit leading-none">
                  {project.title}
                </h3>
                <p className="text-white/40 text-sm leading-relaxed mb-8 max-w-lg h-12 overflow-hidden line-clamp-2">
                  {project.description}
                </p>
                
                <div className="flex flex-wrap items-center gap-8">
                  <Link 
                    href={`/projects/${project.slug}`}
                    className="learn-more-link text-primary font-black text-[10px] tracking-widest uppercase hover:gap-3 transition-all"
                  >
                    View Details <ArrowRight className="w-4 h-4" />
                  </Link>
                  <Link 
                    href={project.demoUrl || "#"}
                    target="_blank"
                    className="flex items-center gap-2 text-white/20 font-black text-[10px] uppercase tracking-widest hover:text-white transition-colors"
                  >
                    Live Demo <ExternalLink className="w-3.5 h-3.5" />
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
